local function setup(x,color,material) x.Anchored=true;x.CanCollide=false;x.CanTouch=false;x.CanQuery=false;x.CastShadow=true;x.TopSurface=Enum.SurfaceType.Smooth;x.BottomSurface=Enum.SurfaceType.Smooth;x.Color=color;x.Material=material or Enum.Material.SmoothPlastic;x.Parent=details;return x end
local function p(name,size,cf,color,material) local x=setup(Instance.new('Part'),color,material);x.Name=name;x.Size=size;x.CFrame=cf;return x end
